Definition obi_seg1_post (retpc : Z) (sp : word) (gp tp : word) (s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra : word)
    (a3v a4v : word) (F : bvmap 5 word) (fc : bv 32) (P src n E lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m' j8,
    ms' = MS (mkR (wz retpc) (wz (bv_unsigned sp - 32)) gp tp t0 t1 t2 s0 s1 (wz (P + 232)) (wz (bv_unsigned sp - 24)) (wz E)
                  a3v a4v a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_READER_PUT) fc None m' (seg_rom usegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono usegs m m' /\ mem_inv usegs m'
    /\ stk usegs m' lo (bv_unsigned sp - 32)
    /\ rw_cells usegs m' (bv_unsigned sp - 32) [CB 8 j8; C8 (wz src); C8 (wz n); C8 ra].

Definition obi_seg1_stmt : Prop := forall (P src n E lo : Z)
    (ra sp : word) gp tp (t0 t1 t2 s0 s1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
    (F : bvmap 5 word) fc (m : mem),
  0 <= P -> P + 344 <= 2^64 -> 0 <= src < 2^64 -> 0 <= n < 2^64 ->
  stk usegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
  mem_inv usegs m ->
  evt usegs (obi_seg1_post P_OBI_RET sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 ra (wz E) a4 F fc P src n E lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz src) (wz n) (wz E) a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ON_BODY_IMPL) fc None m (seg_rom usegs)).
